useAuth

A hook that enables any component to get the current auth & users state & methods.

Example
import { useState } from 'react';
import useAuth from '@/auth/useAuth'

const Component = () => {

    const { authenticated, user, signIn, signOut, signUp, oAuthSignIn } = useAuth()
    const [ error, setError ] = useState<string | null>(null)

    const handleSignIn = async ({ email, password }: { email:string, password: string }) => {

        const result = await signIn({ email, password })

        if (result.status === 'failed') {
            setError(result.message)
        }
    }

    const handleSignUp = async ({ userName, email, password }: { userName: string, email:string, password: string }) => {

        const result = await signUp({ userName, email, password })

        if (result.status === 'failed') {
            setError(result.message)
        }
    }

    const handleGoogleSignIn = async () => {
        oAuthSignIn(async ({redirect, onSignIn}) => {
            try {
                const resp = await apiGoogleOauthSignIn()
                if (resp) {
                    const { token, user } = resp
                    onSignIn({accessToken: token}, user)
                    redirect()
                }
            } catch (error) {
                setError?.((error as string)?.toString() || '')
            }
        })
    }

    const handleSignout = () => {
        signOut()
    }

    return (
        <>
            {authenticated && (
                <div>
                    <h6>Welcome, {user?.userName}</h6>
                    <div>{user?.email}</div>
                </div>
            )}
        </>
    )
}

RETURN	DESCRIPTION	TYPE	DEFAULT
authenticated	State of current authencation	boolean	-
oAuthSignIn	Callback fuction after a single sign on	(callback: (payload: { onSignIn: (tokens: Token, user?: User) => void redirect: () => void }) => void) => void	-
signIn	Sign in handler, return status & message as result	({email: string, password: string}) => ({status: 'success' | 'failed', message: string})	-
signOut	Sign out handler	() => void	-
signUp	Sign up handler, return status & message as result	({userName: string, email: string, password: string}) => ({status: 'success' | 'failed', message: string})	-
user	Signed in user information	{ userId?: string | null avatar?: string | null userName?: string | null email?: string | null authority?: string[] }	-
